package com.securebiz.copilot.api;import com.securebiz.copilot.api.CopilotDtos.*;import com.securebiz.copilot.service.CopilotService;import io.swagger.v3.oas.annotations.Operation;import io.swagger.v3.oas.annotations.tags.Tag;import jakarta.validation.Valid;import org.springframework.web.bind.annotation.*;import java.util.UUID;
@RestController@RequestMapping("/api/v1/security/alerts/{alertId}/copilot")@Tag(name="Security Copilot",description="Read-only evidence-grounded alert analysis")public class CopilotController{private final CopilotService service;public CopilotController(CopilotService service){this.service=service;}@Operation(summary="Ask about a security alert",description="Builds a bounded authorized evidence bundle, treats question/evidence as untrusted and validates returned evidence citations.")@PostMapping("/ask")AskResponse ask(@PathVariable UUID alertId,@Valid@RequestBody AskRequest request){return service.ask(alertId,request);}}
